//! 🧪️ Actual original execution validation retains unknown and over-budget debt independently of job work.
use super::*;
#[test]
fn original_guest_execution_keeps_independent_measured_fuel_and_unknown_debt(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();
 let input=RetainedTurnInput{operation:71,generation:3,epoch:23,grant:semio_framework_value::RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:64}};
 for row in corpus["cases"].as_array().unwrap(){let guest=OriginalJobBudget{input,fuel:row["guestFuel"].as_u64().unwrap(),deadline_us:123456,cancelled:true};let execution=OriginalGuestExecutionBudget{input,fuel:row["executionFuel"].as_u64().unwrap(),deadline_us:guest.deadline_us};execution.validate_for(guest).unwrap();let spent=row["executionSpent"].as_u64().unwrap();OriginalGuestExecutionReceipt{budget:execution,spent_fuel:Some(spent),submitted:true}.validate_for(execution).unwrap();assert_eq!(guest.fuel-row["guestWork"].as_u64().unwrap(),row["remainingGuest"].as_u64().unwrap());assert_eq!(execution.fuel-spent,row["remainingExecution"].as_u64().unwrap());for receipt in[OriginalGuestExecutionReceipt{budget:execution,spent_fuel:None,submitted:true},OriginalGuestExecutionReceipt{budget:execution,spent_fuel:Some(execution.fuel+1),submitted:true},OriginalGuestExecutionReceipt{budget:execution,spent_fuel:Some(1),submitted:false}]{assert!(receipt.validate_for(execution).is_err());}let foreign=OriginalGuestExecutionBudget{input:RetainedTurnInput{epoch:input.epoch+1,..input},..execution};assert!(foreign.validate_for(guest).is_err());let later=OriginalGuestExecutionBudget{deadline_us:execution.deadline_us+1,..execution};assert!(later.validate_for(guest).is_err());OriginalGuestExecutionReceipt{budget:execution,spent_fuel:Some(0),submitted:false}.validate_for(execution).unwrap();}
 eprintln!("[DEBUG] Original guest logical17/work3 and execution1000/instructions127 remain independent; unknown, over-budget, foreign epoch/deadline and unsubmitted nonzero measurement are refused");
}
